const johnnyPages=[
['A bright idea','Every evening, Johnny looked for the little red planet above his garden. Tonight, Pip rolled up beside him and asked what it would be like to visit. Johnny glanced at the empty cardboard box by the fence. “We could build a rocket,” he said, and Pip’s eyes lit up.','Tap Mars, then explore its three craters.','planet'],
['A rocket of their own','Johnny carried the box into his workshop while Pip gathered the pieces they would need. Together, they fitted two sturdy fins to the sides and added a round window for watching the stars. Pip handed you the paints, because this rocket needed your ideas. Whatever you created would carry them all the way to Mars and home again.','Draw, paint, and name the rocket that will fly in your story.','build'],
['A very unusual snack','Before they climbed aboard, Johnny packed three apples in their bag. Pip wanted to help, so he proudly brought over a striped sock. Johnny laughed and explained that socks were useful for warm feet, but not for hungry explorers. Pip put it down and looked hopefully at the apples instead.','Tap each apple to pack it in the bag.','apples'],
['The garden falls away','Johnny and Pip settled into their cardboard rocket and imagined the biggest adventure they could. As they counted down together, the engine began to rumble beneath them. The garden grew smaller through the round window, and Johnny grinned at his friend. Their make-believe journey to Mars had finally begun.','Press Launch and watch the countdown.','launch'],
['A trail through the stars','Beyond the clouds, the sky was filled with tiny lights. Johnny wondered whether they could join a few together to make a trail. Pip stretched out an arm, but floated upside down instead. While Johnny laughed, a bright little star wandered across their path as though it wanted to play.','Light all five stars to make a constellation.','stars'],
['Pip finds his dancing feet','The rocket settled gently onto the red ground, and Johnny stepped out to look around. Pip tried to follow, but his feet tangled together and sent him into a surprising spin. Instead of feeling embarrassed, he turned it into a dance. Soon Johnny was laughing and asking to see another move.','Tap Pip or choose a move for his Mars dance.','robot'],
['The blue planet in the window','After exploring the red hills, Johnny noticed a blue planet shining far away. It was Earth, with its oceans, gardens, and all the people they loved. Mars had been wonderful, but Pip was ready for another apple at home. They climbed back into the rocket and followed the blue light.','Tap Earth to guide the rocket home.','earth'],
['Another adventure is waiting','Johnny opened his eyes and found himself sitting in the cardboard rocket in his own garden. Pip was beside him, holding a picture book they had packed for the journey. They had traveled a very long way in their imaginations. Now they opened the book together, wondering where the next story might take them.','Open the picture book to discover your reward.','book']
];
books[0].pages=johnnyPages;books[0].time='5 min';books[0].summary='Join Johnny and his robot friend Pip as they turn a cardboard box into a rocket. Help them build it, pack their snacks, and find their way through the stars before coming home for another story.';
let generation=0,lastTurn=0,feedbackVersion=0;const timers=new Set(),motions=new Set();
const calm=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function delay(fn,ms){const g=generation;const t=setTimeout(()=>{timers.delete(t);if(g===generation)fn()},ms);timers.add(t)}
function cleanupScene(){generation++;timers.forEach(clearTimeout);timers.clear();motions.forEach(a=>a.cancel());motions.clear();stopSpeech()}
function animate(el,frames,ms=700,after=()=>{}){const g=generation;const a=el.animate(frames,{duration:calm()?1:ms,easing:'cubic-bezier(.2,.7,.3,1)',fill:'forwards'});motions.add(a);a.onfinish=()=>{motions.delete(a);if(g===generation)after(a)};return a}
function bounce(el){animate(el,[{scale:1},{scale:1.18,offset:.45},{scale:1}],500,a=>a.cancel())}
function fly(el,target,after){const a=el.getBoundingClientRect(),b=target.getBoundingClientRect();const x=b.left+b.width/2-a.left-a.width/2,y=b.top+b.height/2-a.top-a.height/2;return animate(el,[{translate:'0 0',scale:1,opacity:1},{translate:`${x*.5}px ${Math.min(y*.5,-65)}px`,scale:1.1,opacity:1,offset:.5},{translate:`${x}px ${y}px`,scale:.15,opacity:0}],750,after)}
function say(text){const el=$('#illFeedback'),v=++feedbackVersion;el.textContent=text;el.classList.add('visible');delay(()=>{if(v===feedbackVersion)el.classList.remove('visible')},2600)}
function goal(text){$('#illInstruction').textContent=text;$('.ill-mission').classList.add('complete')}
function turn(p){if(!book||p<0||p>=book.pages.length||Date.now()-lastTurn<400)return;lastTurn=Date.now();page=p;drawPage()}
function scenery(type){const environment={planet:'garden',build:'workshop',apples:'garden',launch:'garden',stars:'space',robot:'mars',earth:'space',book:'garden',bear:'garden',boots:'garden'}[type]||'garden';return `<div class="ill-backdrop world-${environment}"></div><div class="ill-johnny">${pic('johnny')}</div>${type!=='robot'?`<div class="ill-pip" id="illPip">${pic('pip')}</div>`:''}`}
function drawPage(){cleanupScene();progress[book.id]=page;store.set('pp-progress',progress);const [title,originalText,instruction,type]=book.pages[page];const text=originalText; $('#reader').innerHTML=`<div class="reader-top"><button class="shelf-back" id="backShelf">Bookshelf</button><div class="reader-title">${book.title}<small>${book.demo?'ORIGINAL DEMO STORY':'A CLASSIC, GENTLY RETOLD'}</small></div><span class="page-count">${page+1}<small> / ${book.pages.length}</small></span></div><article class="ill-book"><section class="ill-narration"><div><span class="eyebrow">PAGE ${page+1} · READ TOGETHER</span><h2 id="pageTitle">${title}</h2><p>${text}</p></div>${'speechSynthesis'in window?'<button id="listen" class="ill-listen">Read to me</button>':''}</section><section class="ill-stage ill-scene-${type}" id="illStage" aria-label="Interactive illustration">${scenery(type)}<div id="illObjects"></div><p id="illFeedback" role="status" aria-live="polite"></p><div id="illChoices"></div></section><div class="ill-mission"><div><span class="eyebrow">YOUR PART IN THE STORY</span><p id="illInstruction" aria-live="polite">${instruction}</p></div><button id="replay">Play again</button></div></article><div class="reading-controls"><button class="secondary" id="prev" ${page===0?'disabled':''}>Back</button><div class="page-trail" aria-label="Page ${page+1} of ${book.pages.length}">${book.pages.map((_,i)=>`<span class="${i===page?'current':i<page?'passed':''}">${i+1}</span>`).join('')}</div><button class="primary" id="next">${page===book.pages.length-1?'Finish the story':'Next page'}</button></div>`;
$('#backShelf').onclick=home;$('#prev').onclick=()=>turn(page-1);$('#next').onclick=()=>{if(page===book.pages.length-1)finish();else turn(page+1)};$('#replay').onclick=()=>{if(Date.now()-lastTurn<300)return;lastTurn=Date.now();drawPage()};
if($('#listen'))$('#listen').onclick=()=>{if(speechSynthesis.speaking){stopSpeech();$('#listen').textContent='Read to me';return}const g=generation,u=new SpeechSynthesisUtterance($('.ill-narration>div').innerText);u.rate=.86;u.onend=u.onerror=()=>{if(g===generation&&$('#listen'))$('#listen').textContent='Read to me'};speechSynthesis.speak(u);$('#listen').textContent='Stop reading'};
play(type);if(book.id==='johnny'&&rocketDesign.ready&&['launch','stars','robot','earth','book'].includes(type)){const note=document.createElement('p');note.className='rocket-story-note';note.textContent=['launch','stars','earth'].includes(type)?'Johnny and Pip are flying '+rocketDesign.name+', the rocket you made.':type==='robot'?'Your rocket, '+rocketDesign.name+', is waiting beside the red hills.':'You brought '+rocketDesign.name+' home, ready for your next adventure.';$('.ill-narration>div').append(note);if(['stars','robot','book'].includes(type)){const model=document.createElement('div');model.className='ill-prop returning-rocket';model.innerHTML=rocketPicture();$('#illObjects').prepend(model)}}
}
function play(type){const stage=$('#illStage'),root=$('#illObjects');let count=0,arrived=0,busy=false,done=false;const found=new Set();
const object=(asset,label,cls,x,y,action)=>{const b=document.createElement('button');b.className='ill-object '+cls;b.style.left=x+'%';b.style.top=y+'%';b.setAttribute('aria-label',label);b.innerHTML=pic(asset);root.append(b);let last=0;b.onclick=()=>{if(b.disabled||!b.isConnected||Date.now()-last<100)return;last=Date.now();action(b)};return b};
const prop=(asset,cls,x,y)=>{const d=document.createElement('div');d.className='ill-prop '+cls;d.style.left=x+'%';d.style.top=y+'%';d.innerHTML=asset==='rocket'&&book.id==='johnny'?rocketPicture():pic(asset);root.append(d);return d};
const label=(el,text)=>{const s=el.querySelector('.ill-label')||document.createElement('span');s.className='ill-label';s.textContent=text;el.append(s)};
const choice=(text,fn)=>{const b=document.createElement('button');b.textContent=text;b.className='ill-choice';$('#illChoices').append(b);b.onclick=()=>{if(busy)return;fn(b)};return b};
if(type==='planet'){
prop('telescope','ill-telescope',28,73);
const mars=object('mars','Take a closer look at Mars','ill-planet',64,33,b=>{if(done){say('Mars is ready for your visit. Let’s build a rocket!');bounce(b);return}done=true;stage.classList.add('ill-zoom');say('Can you find the three craters on Mars?');$('#illInstruction').textContent='Tap each numbered crater to explore it.';
[[56,21],[71,33],[60,46]].forEach(([x,y],i)=>{const dot=document.createElement('button');dot.className='ill-crater';dot.style.left=x+'%';dot.style.top=y+'%';dot.textContent=i+1;dot.setAttribute('aria-label','Explore crater '+(i+1));root.append(dot);dot.onclick=()=>{if(found.has(i))return;found.add(i);dot.classList.add('found');dot.disabled=true;bounce(mars);say(['This crater looks like a giant bowl!','This little crater has a bumpy edge.','This one could hide a whole playground!'][i]);if(found.size===3)goal('You explored all three craters. Now let’s build a rocket!')}})
});label(mars,'Look closer');
}else if(type==='build'){
if(!rocketDesign.ready){openRocketWorkshop();return}
const rocket=prop('rocket','ill-build-rocket',52,45);rocket.style.opacity='.16';label(rocket,rocketDesign.name);$('#illInstruction').textContent='Tap your painted parts to put your rocket together.';
[['Body',18,48,'inset(29% 26% 23% 26%)'],['Nose',48,20,'inset(0 20% 70% 20%)'],['Fins',80,65,'polygon(0 53%,30% 53%,30% 76%,70% 76%,70% 53%,100% 53%,100% 100%,0 100%)']].forEach(([name,x,y,clip],i)=>{const piece=object('rocket','Attach my '+name.toLowerCase(),'custom-piece',x,y,b=>{if(found.has(i))return;found.add(i);b.disabled=true;fly(b,rocket,()=>{b.hidden=true;arrived++;rocket.style.opacity=String(.16+arrived*.84/3);bounce(rocket);say('Your '+name.toLowerCase()+' fits into place!');if(arrived===3)goal('You built '+rocketDesign.name+'! Your rocket is ready for Mars.')})});piece.innerHTML=rocketPicture();piece.querySelector('img').style.clipPath=clip;label(piece,name)});choice('Change my design',openRocketWorkshop);
}else if(type==='apples'){
const bag=prop('bag','ill-bag',52,72);label(bag,'0 of 3 packed');
[[21,34],[51,22],[78,35]].forEach(([x,y],i)=>object('apple','Pack apple '+(i+1),'ill-apple',x,y,b=>{if(found.has(i))return;found.add(i);b.disabled=true;fly(b,bag,()=>{b.hidden=true;arrived++;bag.querySelector('.ill-label').textContent=arrived+' of 3 packed';bounce(bag);say(['The first apple drops into the bag.','There are two apples ready for the trip.','All three apples are safely packed!'][arrived-1]);if(arrived===3){goal('Pip looks hungry. Give him a little apple snack!');const snack=object('apple','Give Pip an apple','ill-bonus-apple',72,56,b=>{if(busy)return;busy=true;b.disabled=true;fly(b,$('#illPip'),()=>{b.hidden=true;bounce($('#illPip'));stage.classList.add('ill-happy-pip');say('Pip munches happily and gives you a big thank-you!');goal('Everyone is ready. Let’s launch your rocket!')})});label(snack,'For Pip')}})}));
const sock=object('sock','Show Pip the silly sock','ill-sock',30,69,b=>{animate(b,[{rotate:'0deg'},{translate:'0 -70px',rotate:'50deg'},{translate:'0 0',rotate:'-15deg'}],700,a=>a.cancel());say('Pip wrinkles his nose. That sock smells like feet!')});label(sock,'What is this?');
}else if(type==='launch'){
const ship=prop('rocket','ill-launch-ship',43,48);const cloud=prop('cloud','ill-exhaust',43,82);cloud.hidden=true;
const start=choice('Launch the rocket',b=>{if(busy)return;busy=true;b.disabled=true;let n=3;const badge=document.createElement('div');badge.className='ill-countdown';badge.textContent=n;root.append(badge);say('Johnny and Pip are counting down with you!');
delay(()=>{badge.textContent=2;bounce(badge)},700);delay(()=>{badge.textContent=1;cloud.hidden=false;bounce(badge);stage.classList.add('ill-engine-on')},1400);
delay(()=>{badge.remove();stage.classList.remove('ill-engine-on');say('Your rocket is lifting off!');animate(cloud,[{scale:.5,opacity:0},{scale:1.5,opacity:1},{scale:2,opacity:0}],1300);animate(ship,[{translate:'0 0'},{translate:'0 -600px'}],1400,()=>{stage.classList.add('ill-orbit');$('.ill-backdrop').className='ill-backdrop world-space';cloud.hidden=true;ship.getAnimations().forEach(a=>a.cancel());animate(ship,[{scale:.25,translate:'0 -70px',rotate:'30deg',opacity:0},{scale:.7,translate:'0 0',rotate:'15deg',opacity:1}],700);busy=false;b.hidden=true;goal('You’re in space! Give your rocket an extra boost.');choice('Give it a boost',()=>{if(busy)return;busy=true;animate(ship,[{translate:'0 0',rotate:'15deg',scale:.7},{translate:'90px -65px',rotate:'-20deg',scale:.6},{translate:'0 0',rotate:'15deg',scale:.7}],1200,()=>{busy=false});say('Johnny cheers as the rocket swoops past the stars!')})})},2100)
});
}else if(type==='stars'){
const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('preserveAspectRatio','none');svg.classList.add('ill-star-path');svg.innerHTML='<path pathLength="1" d="M18 30 L36 16 L55 37 L73 17 L84 49"/>';stage.prepend(svg);
[[18,30],[36,16],[55,37],[73,17],[84,49]].forEach(([x,y],i)=>object('star','Light star '+(i+1),'ill-star',x,y,b=>{bounce(b);if(found.has(i)){say('Your star shines a little brighter!');return}found.add(i);b.classList.add('shining');count++;$('#illInstruction').textContent=count+' of 5 stars are glowing.';if(count===5){stage.classList.add('ill-connected');say('Your stars have made a beautiful trail!');goal('A wandering star wants to join you. Can you catch it?');delay(()=>{const comet=object('star','Catch the wandering star','ill-comet',35,60,b=>{b.classList.remove('wandering');b.disabled=true;animate(b,[{scale:1},{scale:1.8,opacity:0}],650,()=>b.hidden=true);say('You caught it! Pip is so surprised he spins upside down.');animate($('#illPip'),[{rotate:'0deg'},{rotate:'360deg'}],1000,a=>a.cancel());goal('Your constellation is complete. Mars is waiting!')});label(comet,'Catch me');comet.classList.add('wandering')},700)}}));
}else if(type==='robot'){
const pip=object('pip','Make Pip dance','ill-dancing-pip',55,55,()=>dance(count++%3));label(pip,'Tap Pip');
function dance(i){if(busy)return;busy=true;stage.dataset.dance=i;const moves=[[{rotate:'0deg',scale:1},{rotate:'180deg',scale:1.1},{rotate:'360deg',scale:1}],[{translate:'0 0',scale:1},{translate:'0 -85px',scale:1.12},{translate:'0 0',scale:1}],[{rotate:'0deg'},{rotate:'-22deg',offset:.25},{rotate:'22deg',offset:.5},{rotate:'-15deg',offset:.75},{rotate:'0deg'}]];animate(pip,moves[i],950,a=>{a.cancel();busy=false});$('#illChoices').querySelectorAll('button').forEach((b,j)=>b.classList.toggle('chosen',j===i));say(['Pip spins like a tiny washing machine!','His springy feet send him bouncing into the air!','Pip wiggles as though his arms are made of noodles!'][i]);goal('Choose another move to help Pip make up his dance.')}
['Spin','Bounce','Wiggle'].forEach((name,i)=>choice(name,()=>dance(i)));
}else if(type==='earth'){
const rocket=prop('rocket','ill-home-rocket',27,59);
const earth=object('earth','Fly home to Earth','ill-earth',75,32,b=>{if(busy)return;busy=true;if(done){rocket.getAnimations().forEach(a=>a.cancel());$('.ill-home-house')?.remove();$('.ill-backdrop').className='ill-backdrop world-space';stage.classList.remove('ill-home-arrival')}say('Johnny points the rocket toward the blue planet.');fly(rocket,b,()=>{done=true;busy=false;$('.ill-backdrop').className='ill-backdrop world-garden';stage.classList.add('ill-home-arrival');prop('house','ill-home-house',31,52);bounce($('#illPip'));say('They’ve landed beside their very own garden!');goal('You brought them home. There’s one more surprise ahead.');b.querySelector('.ill-label').textContent='Fly again'})});label(earth,'Fly home');
}else if(type==='book'){
const story=object('book','Open the illustrated book','ill-story-book',51,56,b=>{if(done)return;done=true;b.disabled=true;animate(b,[{rotate:'0deg',scale:1},{rotate:'-12deg',scale:1.15},{rotate:'0deg',scale:1}],600,()=>{b.innerHTML=pic('openbook');stage.classList.add('ill-book-reveal');say('The book has a special surprise for its reader.');const prize=object('star','Collect your story star','ill-prize',52,24,s=>{s.disabled=true;animate(s,[{scale:1},{scale:1.4},{translate:'0 -30px',scale:1}],650);goal('You earned your story star! Finish the story to celebrate.');say('Johnny and Pip are glad you came along!');label(s,'Story explorer');bounce($('#illPip'))});label(prize,'This one is yours');animate(prize,[{translate:'0 85px',scale:.1,opacity:0},{translate:'0 0',scale:1,opacity:1}],700)})});label(story,'Open the book');
}else{
const asset=type==='boots'?'boots':'bear';object(asset,type==='boots'?'Make the boots dance':'Make the bear wave','ill-extra',50,50,b=>{animate(b,[{rotate:'0deg'},{rotate:'-15deg',translate:'0 -30px'},{rotate:'15deg'},{rotate:'0deg',translate:'0 0'}],800,a=>a.cancel());say(type==='boots'?'These boots are ready to dance down the road!':'The bear waves hello to its new reading friend!');goal('You can play again or turn the page when you’re ready.')})
}
}
